{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.production_pipeline_data as with a as ( SELECT CASE WHEN subvention IS NULL OR subvention = \'\' THEN NULL ELSE SPLIT_PART( SPLIT_PART( REGEXP_REPLACE(TRIM(subvention), \'\\s+\', \'\'), \'/\', 1 ), \'-\', 1 ) || CASE WHEN SPLIT_PART( SPLIT_PART( REGEXP_REPLACE(TRIM(subvention), \'\\s+\', \'\'), \'/\', 1 ), \'-\', 2 ) <> \'\' THEN \'-\' || SPLIT_PART( SPLIT_PART( REGEXP_REPLACE(TRIM(subvention), \'\\s+\', \'\'), \'/\', 1 ), \'-\', 2 ) ELSE \'\' END END AS normalized_sku, Proj_qty, SKU_STATUS_, expected_delivery_date, revised_delivery_date, factory_name, incharg_name incharge_name, ifnull(revised_delivery_date, expected_delivery_date) FDD, category, lower( CASE WHEN CATEGORY IS NULL OR TRIM(CATEGORY) = \'\' THEN NULL WHEN LOWER(CATEGORY) LIKE \'%trackpants%\' THEN \'Trackpants\' WHEN LOWER(CATEGORY) LIKE \'%sweatshirt%\' THEN \'Sweatshirt\' WHEN REGEXP_LIKE(LOWER(CATEGORY), \'.*t[-_ ]?shirt.*|.*tee.*\') THEN \'Tshirts\' WHEN LOWER(CATEGORY) LIKE \'%overshirt%\' THEN \'Overshirt\' WHEN LOWER(CATEGORY) LIKE \'%cargo%\' THEN \'Cargo\' WHEN LOWER(CATEGORY) LIKE \'%jogger%\' THEN \'Joggers\' WHEN LOWER(CATEGORY) LIKE \'%trouser%\' OR LOWER(CATEGORY) LIKE \'%pant%\' THEN \'Trousers\' WHEN LOWER(CATEGORY) LIKE \'%chino%\' THEN \'Chino\' WHEN LOWER(CATEGORY) LIKE \'%short%\' THEN \'Shorts\' WHEN LOWER(CATEGORY) LIKE \'%pyjama%\' OR LOWER(CATEGORY) LIKE \'%pj%\' THEN \'Pyjamas\' WHEN LOWER(CATEGORY) LIKE \'%denim%\' THEN \'Denim\' WHEN LOWER(CATEGORY) LIKE \'%jean%\' THEN \'Jeans\' WHEN LOWER(CATEGORY) LIKE \'%hoodie%\' THEN \'Hoodies\' WHEN LOWER(CATEGORY) LIKE \'%sweater%\' THEN \'Sweater\' WHEN LOWER(CATEGORY) LIKE \'%shirt%\' THEN \'Shirts\' WHEN LOWER(CATEGORY) LIKE \'%jacket%\' THEN \'Jackets\' WHEN LOWER(CATEGORY) LIKE \'%blazer%\' THEN \'Blazer\' WHEN REGEXP_LIKE(LOWER(CATEGORY), \'.*coord.*|.*co-ord.*\') THEN \'Coords\' WHEN LOWER(CATEGORY) LIKE \'%boxer%\' THEN \'Boxers\' WHEN LOWER(CATEGORY) LIKE \'%innerwear%\' OR LOWER(CATEGORY) LIKE \'%vest%\' OR LOWER(CATEGORY) LIKE \'%brief%\' THEN \'Innerwear\' WHEN LOWER(CATEGORY) LIKE \'%shoe%\' OR LOWER(CATEGORY) LIKE \'%sneaker%\' OR LOWER(CATEGORY) LIKE \'%slipper%\' THEN \'Shoes\' WHEN LOWER(CATEGORY) LIKE \'%sunglass%\' THEN \'Sunglasses\' WHEN LOWER(CATEGORY) LIKE \'%belt%\' THEN \'Belts\' WHEN LOWER(CATEGORY) LIKE \'%bag%\' THEN \'Bags\' WHEN LOWER(CATEGORY) LIKE \'%accessor%\' THEN \'Accessories\' WHEN LOWER(CATEGORY) LIKE \'%perfume%\' OR LOWER(CATEGORY) LIKE \'%fragrance%\' THEN \'Perfumes\' ELSE category END ) AS cleaned_category FROM snitch_db.maplemonk.gs_product_tracking_new_main WHERE sku_status_ not in (\'Delivered\', \'Cancel\', \'Hold\') and LOWER(sku_status_) not LIKE \'deliver%\' and LOWER(sku_status_) not LIKE \'cancel%\' and LOWER(sku_status_) not LIKE \'hold\' ) select * from a;",
                    "transaction": true
